# -*- coding: utf-8 -*-
from contextlib import contextmanager
import threading
from time import sleep

import queue


def wait_to_limit_number_of_read_calls():
    sleep(0.1)


class StreamEnqueuer(threading.Thread):
    def __init__(self, stream):
        self._stream = stream
        self._queue = None
        self._lock = threading.Lock()
        self._enquerer_stopped = threading.Event()
        super(StreamEnqueuer, self).__init__()

    def run(self):
        while not self._is_enquerer_stopped():
            chunk = self._stream.read(timeout=0.1)
            if chunk is not None:
                self._try_enqueueing(chunk)
            wait_to_limit_number_of_read_calls()

    def stop(self):
        self._enquerer_stopped.set()

    @contextmanager
    def enqueue(self):
        self._set_queue(queue.Queue())
        try:
            yield self._queue
        finally:
            self._set_queue(None)

    def _is_enquerer_stopped(self):
        return self._enquerer_stopped.is_set()

    def _try_enqueueing(self, chunk):
        with self._lock:
            if self._queue:
                self._queue.put(chunk)

    def _set_queue(self, queue):
        with self._lock:
            self._queue = queue
